fn check_if_last_char_is_a_letter(txt: &str) -> bool {
    let mut it = txt.chars();
    let Some(mut prev) = it.next() else {
        return false; // empty
    };

    let mut last = prev;
    for c in it {
        prev = last;
        last = c;
    }

    if !last.is_ascii_alphabetic() {
        return false;
    }

    // Either single-character string, or preceding char is a space.
    last == prev || prev == ' '
}